:root {
  --bg-1: #07131f;
  --bg-2: #122942;
  --panel: rgba(11, 23, 34, 0.82);
  --panel-border: rgba(157, 201, 255, 0.2);
  --primary: #7ce0ff;
  --secondary: #79ffb0;
  --accent: #ffcc70;
  --danger: #ff7a7a;
  --food: #ff6b6b;
  --snake-head: #7ef1a3;
  --snake-body: #4cc36b;
  --grid: rgba(255, 255, 255, 0.06);
  --text: #ebf8ff;
  --muted: #b6cedd;
  --shadow: rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  font-family: Inter, "Segoe UI", sans-serif;
  background: radial-gradient(circle at top, #123d68 0%, var(--bg-1) 32%, #050d16 100%);
  color: var(--text);
}

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 20px;
}

button {
  font: inherit;
}

.game-shell {
  width: min(100%, 620px);
  padding: 18px 18px 16px;
  border-radius: 24px;
  background: rgba(10, 19, 29, 0.8);
  border: 1px solid var(--panel-border);
  box-shadow: 0 24px 60px var(--shadow);
  backdrop-filter: blur(10px);
}

.hud {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}

.brand-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand {
  font-size: clamp(1.3rem, 2vw, 1.9rem);
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--primary);
}

.stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.stat-card {
  min-width: 78px;
  padding: 8px 10px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  text-align: center;
}

.label {
  display: block;
  font-size: 0.66rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 4px;
}

.stat-card strong {
  font-size: 1.1rem;
}

.board-panel {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(12, 31, 21, 0.88), rgba(6, 15, 27, 0.92));
  border: 1px solid rgba(255, 255, 255, 0.08);
}

canvas {
  width: 100%;
  max-width: 100%;
  height: auto;
  display: block;
  aspect-ratio: 1;
  background: rgba(8, 18, 25, 0.6);
}

.overlay {
  position: absolute;
  inset: 0;
  display: none;
  place-items: center;
  background: rgba(6, 12, 19, 0.5);
  backdrop-filter: blur(3px);
}

.overlay.visible {
  display: grid;
}

.overlay-card {
  width: min(85%, 360px);
  padding: 20px 20px 24px;
  border-radius: 20px;
  text-align: center;
  background: rgba(11, 26, 35, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.3);
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--accent);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 0.72rem;
}

.overlay-card h1 {
  margin: 0 0 10px;
  font-size: clamp(2rem, 5vw, 2.8rem);
}

.overlay-card p {
  margin: 0 0 18px;
  color: var(--muted);
  line-height: 1.6;
}

#start-button,
.control-btn {
  border: 0;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.15s ease, filter 0.15s ease;
}

#start-button {
  background: linear-gradient(135deg, var(--primary), #6ad7ff);
  color: #05263b;
  font-weight: 800;
  padding: 12px 18px;
  min-width: 140px;
}

#start-button:hover,
.control-btn:hover {
  transform: translateY(-1px);
  filter: brightness(1.04);
}

.controls {
  display: grid;
  justify-items: center;
  gap: 8px;
  margin-top: 16px;
}

.middle-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.control-btn {
  width: 68px;
  height: 58px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 1.6rem;
  font-weight: 700;
  box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.06);
}

.control-btn.accent {
  width: 106px;
  font-size: 0.98rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: linear-gradient(180deg, rgba(124, 224, 255, 0.18), rgba(124, 224, 255, 0.06));
}

@media (max-width: 520px) {
  .game-shell {
    padding: 14px 12px 12px;
  }

  .hud {
    flex-direction: column;
    align-items: stretch;
  }

  .stats {
    justify-content: space-between;
  }

  .stat-card {
    flex: 1;
  }

  .controls {
    margin-top: 12px;
  }
}

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best-score');
const speedEl = document.getElementById('speed');
const overlay = document.getElementById('overlay');
const startButton = document.getElementById('start-button');
const pauseButton = document.getElementById('pause-button');
const controlButtons = Array.from(document.querySelectorAll('[data-dir]'));

const GRID_SIZE = 20;
const CELL_SIZE = canvas.width / GRID_SIZE;
const INITIAL_TICK_MS = 170;
const MIN_TICK_MS = 75;
const SPEED_STEP = 7;

const directions = {
  up: { x: 0, y: -1 },
  down: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
  right: { x: 1, y: 0 },
};

let snake;
let direction;
let queuedDirection;
let food;
let obstacles;
let score;
let bestScore;
let tickMs;
let lastMove;
let isPlaying;
let isPaused;

const storageKey = 'snake-rush-best-score';

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function loadBestScore() {
  const stored = Number.parseInt(localStorage.getItem(storageKey) || '0', 10);
  bestScore = Number.isFinite(stored) ? stored : 0;
  bestEl.textContent = String(bestScore);
}

function resetGame() {
  snake = [
    { x: 8, y: 10 },
    { x: 7, y: 10 },
    { x: 6, y: 10 },
  ];
  direction = directions.right;
  queuedDirection = directions.right;
  obstacles = generateObstacles();
  food = randomFood();
  score = 0;
  tickMs = INITIAL_TICK_MS;
  lastMove = 0;
  isPaused = false;
  pauseButton.textContent = 'Pause';
  updateHud();
}

function startGame() {
  resetGame();
  isPlaying = true;
  overlay.classList.remove('visible');
  requestAnimationFrame(gameLoop);
}

function endGame() {
  isPlaying = false;
  if (score > bestScore) {
    bestScore = score;
    localStorage.setItem(storageKey, String(bestScore));
    bestEl.textContent = String(bestScore);
  }
  overlay.classList.add('visible');
  overlay.querySelector('h1').textContent = 'Game Over';
  overlay.querySelector('p').textContent = `Final score: ${score}. Press the button below to play again.`;
  startButton.textContent = 'Play Again';
}

function setPaused(nextPaused) {
  if (!isPlaying) {
    return;
  }
  isPaused = nextPaused;
  pauseButton.textContent = isPaused ? 'Resume' : 'Pause';
}

function setDirection(nextDirection) {
  if (!isPlaying) {
    return;
  }

  const isOpposite =
    nextDirection.x === -direction.x && nextDirection.y === -direction.y;

  if (!isOpposite) {
    queuedDirection = nextDirection;
  }
}

function generateObstacles() {
  const list = new Set();
  const count = 8;

  while (list.size < count) {
    const x = Math.floor(Math.random() * GRID_SIZE);
    const y = Math.floor(Math.random() * GRID_SIZE);
    const isNearStart = (x >= 5 && x <= 11 && y >= 9 && y <= 11);

    if (!isNearStart) {
      list.add(`${x},${y}`);
    }
  }

  return [...list].map((entry) => {
    const [x, y] = entry.split(',').map(Number);
    return { x, y };
  });
}

function isOccupied(cell, ignoreTail = false) {
  if (obstacles.some((obstacle) => obstacle.x === cell.x && obstacle.y === cell.y)) {
    return true;
  }

  for (let index = 0; index < snake.length; index += 1) {
    const part = snake[index];
    const shouldIgnore = ignoreTail && index === snake.length - 1 && !foodIsConsumed(cell);
    if (shouldIgnore) {
      continue;
    }
    if (part.x === cell.x && part.y === cell.y) {
      return true;
    }
  }

  return false;
}

function foodIsConsumed(cell) {
  return food && cell.x === food.x && cell.y === food.y;
}

function randomFood() {
  let candidate;
  let attempts = 0;

  do {
    candidate = {
      x: Math.floor(Math.random() * GRID_SIZE),
      y: Math.floor(Math.random() * GRID_SIZE),
    };
    attempts += 1;
  } while ((isOccupied(candidate, false) || attempts < 200) && attempts < 300);

  return candidate;
}

function updateHud() {
  scoreEl.textContent = String(score);
  bestEl.textContent = String(bestScore);
  speedEl.textContent = `${(INITIAL_TICK_MS / tickMs).toFixed(1)}x`;
}

function stepGame() {
  direction = queuedDirection;
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (
    head.x < 0 ||
    head.x >= GRID_SIZE ||
    head.y < 0 ||
    head.y >= GRID_SIZE ||
    isOccupied(head, true)
  ) {
    endGame();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score += 10;
    tickMs = clamp(INITIAL_TICK_MS - score * 0.8, MIN_TICK_MS, INITIAL_TICK_MS);
    food = randomFood();
    if (score > bestScore) {
      bestScore = score;
      localStorage.setItem(storageKey, String(bestScore));
    }
  } else {
    snake.pop();
  }

  updateHud();
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#081924';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let x = 0; x < GRID_SIZE; x += 1) {
    for (let y = 0; y < GRID_SIZE; y += 1) {
      ctx.fillStyle = (x + y) % 2 === 0 ? 'rgba(255,255,255,0.02)' : 'rgba(255,255,255,0.04)';
      ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    }
  }

  obstacles.forEach((cell) => {
    ctx.fillStyle = '#405c7a';
    ctx.fillRect(cell.x * CELL_SIZE + 2, cell.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);
  });

  ctx.fillStyle = '#ff6b6b';
  ctx.beginPath();
  ctx.arc(food.x * CELL_SIZE + CELL_SIZE / 2, food.y * CELL_SIZE + CELL_SIZE / 2, CELL_SIZE * 0.34, 0, Math.PI * 2);
  ctx.fill();

  snake.forEach((segment, index) => {
    const x = segment.x * CELL_SIZE;
    const y = segment.y * CELL_SIZE;

    ctx.fillStyle = index === 0 ? '#7ef1a3' : '#4cc36b';
    ctx.fillRect(x + 1, y + 1, CELL_SIZE - 2, CELL_SIZE - 2);

    if (index === 0) {
      ctx.fillStyle = '#0d2c24';
      ctx.fillRect(x + CELL_SIZE * 0.55, y + CELL_SIZE * 0.3, CELL_SIZE * 0.18, CELL_SIZE * 0.18);
      ctx.fillRect(x + CELL_SIZE * 0.25, y + CELL_SIZE * 0.3, CELL_SIZE * 0.18, CELL_SIZE * 0.18);
    }
  });
}

function gameLoop(timestamp) {
  if (isPlaying && !isPaused && timestamp - lastMove >= tickMs) {
    stepGame();
    lastMove = timestamp;
  }

  drawBoard();

  if (isPlaying) {
    requestAnimationFrame(gameLoop);
  }
}

function handleDirectionInput(directionName) {
  if (!isPlaying && directionName) {
    startGame();
  }
  if (isPlaying) {
    setDirection(directions[directionName]);
  }
}

startButton.addEventListener('click', () => {
  overlay.classList.remove('visible');
  startGame();
});

pauseButton.addEventListener('click', () => {
  if (!isPlaying) {
    startGame();
    return;
  }
  setPaused(!isPaused);
});

controlButtons.forEach((button) => {
  button.addEventListener('click', () => {
    const directionName = button.dataset.dir;
    handleDirectionInput(directionName);
  });
});

document.addEventListener('keydown', (event) => {
  const key = event.key.toLowerCase();
  const map = {
    arrowup: 'up',
    w: 'up',
    arrowdown: 'down',
    s: 'down',
    arrowleft: 'left',
    a: 'left',
    arrowright: 'right',
    d: 'right',
    ' ': 'pause',
  };

  const directionName = map[key];

  if (!directionName) {
    return;
  }

  event.preventDefault();

  if (directionName === 'pause') {
    pauseButton.click();
    return;
  }

  if (!isPlaying) {
    startGame();
  }

  setDirection(directions[directionName]);
});

loadBestScore();
resetGame();
drawBoard();

