  await evaluate(`document.querySelector('#start-button').click()`);
  await evaluate(`food = {x: snake[0].x + 1, y: snake[0].y}`);
  await sleep(250);
  const ate = await evaluate(`({score, playing: isPlaying})`);
  if (ate.score !== 10 || !ate.playing) throw new Error(`Fruit collection failed: ${JSON.stringify(ate)}`);
  await evaluate(`document.querySelector('#pause-button').click()`);
  const paused = await evaluate(`({paused: isPaused, label: document.querySelector('#pause-button').textContent})`);
  if (!paused.paused || paused.label !== 'Resume') throw new Error(`Pause failed: ${JSON.stringify(paused)}`);
  await evaluate(`document.querySelector('#pause-button').click(); snake = [{x: 19, y: 0}, {x: 18, y: 0}, {x: 17, y: 0}]; direction = queuedDirection = directions.right; lastMove = 0`);
  await sleep(250);
  const ended = await evaluate(`({playing: isPlaying, title: document.querySelector('#overlay h1').textContent, visible: document.querySelector('#overlay').classList.contains('visible')})`);
  if (ended.playing || ended.title !== 'Game Over' || !ended.visible) throw new Error(`Wall collision failed: ${JSON.stringify(ended)}`);
  await evaluate(`document.querySelector('#start-button').click()`);
  const replay = await evaluate(`({playing: isPlaying, title: document.querySelector('#overlay h1').textContent, visible: document.querySelector('#overlay').classList.contains('visible')})`);
  if (!replay.playing || replay.title !== 'Snake Rush' || replay.visible) throw new Error(`Replay reset failed: ${JSON.stringify(replay)}`);
  console.log(JSON.stringify({initial, ate, paused, ended, replay}, null, 2));
  ws.close();
})().catch((error) => { console.error(error); process.exitCode = 1; });
